/* Nose and Sinus Disease content derived only from "Nose and Sinus Disease 2026- Student.pptx", its speaker notes, and matching objectives. */
(function () {
  "use strict";

  var questionSequence = 0;
  function Q(prompt, answer, distractors, explanation) {
    var correct = questionSequence++ % 4;
    var choices = (distractors || []).slice(0, 3);
    while (choices.length < 3) choices.push("Not supported by the lecture");
    choices.splice(correct, 0, answer);
    return { prompt: prompt, choices: choices, correct: correct, explanation: explanation };
  }
  function C(title, html, tests, application, highYield) {
    return { title: title, html: html, body: title, tests: tests || [], application: application || [], highYield: !!highYield };
  }
  function K(title, html, test, application, highYield) {
    return C(title, html, [Q(test[0], test[1], test[2], test[3])], [Q(application[0], application[1], application[2], application[3])], highYield);
  }
  function T(headers, rows) {
    return '<table class="learn-table"><tr>' + headers.map(function (header) { return '<th>' + header + '</th>'; }).join('') + '</tr>' + rows.map(function (row) { return '<tr>' + row.map(function (cell) { return '<td>' + cell + '</td>'; }).join('') + '</tr>'; }).join('') + '</table>';
  }
  function M(label, text) {
    return '<div class="box-mnemonic"><span class="lbl">' + label + '</span><strong>' + text + '</strong></div>';
  }

  var objectiveStatements = {
    "01-polyp-features": "Identify the characteristics of nasal polyps and how they present symptomatically and on physical exam.",
    "02-polyp-associations": "Identify the patient populations frequently associated with nasal polyps and recall the components of Samter’s triad.",
    "03-polyp-treatment": "Recall the treatment of nasal polyps.",
    "04-ar-pathogenesis": "Define allergic rhinitis and explain the pathogenesis and common etiologies of allergic rhinitis.",
    "05-ar-risks": "Identify the medical conditions that are associated with allergic rhinitis as well as additional risk factors.",
    "06-ar-presentation": "Recognize the symptoms and characteristic physical exam findings associated with allergic rhinitis.",
    "07-ar-diagnosis": "Review how the diagnosis of allergic rhinitis is made.",
    "08-ar-treatment": "Recognize the three main components of treating allergic rhinitis as well as the general approach to treating patients with persistent symptoms, moderate to severe symptoms, intermittent symptoms and chronic symptoms.",
    "09-nasal-steroids": "Briefly describe the mechanism of action of nasal glucocorticoids and recall which glucocorticoids are associated with limited to no systemic bioavailability",
    "10-steroid-effects": "Recognize the potential adverse effects of nasal glucocorticoids",
    "11-antihistamines": "Identify which antihistamines are first and second-generation agents as well as the benefits of using second-generation antihistamines. Recall the adverse effects of the first-generation antihistamines.",
    "12-ar-adjuncts": "Recognize adjunct therapies for allergic rhinitis that can be used in conjunction with or in place of antihistamines and nasal steroids.",
    "13-rhinitis-medicamentosa": "Identify rhinitis medicamentosa as well as the preceding risk factors and treatment.",
    "14-sinus-pathophysiology": "Review the pathophysiology of sinus disease, specifically the three mechanisms in which sinus infections occur",
    "15-rhinosinusitis-duration": "Classify rhinosinusitis via timing of the disease",
    "16-viral-bacterial": "Compare and contrast viral rhinosinusitis and bacterial rhinosinusitis in terms of their timing, clinical features, and treatment.",
    "17-pathogens": "Recall the pathogens that are responsible for most cases of viral and bacterial rhinosinusitis.",
    "18-abrs-antibiotics": "Recall the antibiotic choices for various populations being treated for bacterial rhinosinusitis.",
    "19-abrs-complications": "Recognize the complications associated with bacterial rhinosinusitis based on how they present.",
    "20-crs-subtypes": "Identify chronic rhinosinusitis and its three clinical subtypes.",
    "21-crs-comparison": "Compare and contrast the three types of chronic sinusitis in terms of their pathophysiology, risk factors and associated medical conditions, characteristic clinical features as well as diagnostic findings.",
    "22-crs-diagnosis": "Recall the four cardinal symptoms used in diagnosing chronic rhinosinusitis and the objective inflammatory findings that meet diagnostic criteria.",
    "23-crs-treatment": "Review the goals in treating chronic rhinosinusitis and the methods in treating each clinical subtype."
  };

  function O(id, title, cards) {
    var test = [], apply = [];
    cards.forEach(function (card, cardIndex) {
      (card.tests || []).forEach(function (question) {
        test.push({ prompt: question.prompt, choices: question.choices, correct: question.correct, explanation: question.explanation, card: cardIndex });
      });
      (card.application || []).forEach(function (question) {
        apply.push({ prompt: question.prompt, choices: question.choices, correct: question.correct, explanation: question.explanation, card: cardIndex });
      });
    });
    return { id: id, title: title, description: objectiveStatements[id] || "", cards: cards, test: test, apply: apply };
  }

  window.NOSE_SINUS_OBJECTIVES = [
    O("01-polyp-features", "1. Nasal Polyps: Features and Exam", [
      K("Appearance and origin", `<p>Nasal polyps are benign, smooth, rounded, semitransparent, glistening masses filled with inflammatory material. Their color ranges from pale or gray to erythematous. They form in the nasal cavity or paranasal sinuses and are often bilateral.</p><p>The <strong>middle meatus</strong>, derived from the ethmoid sinus, is their most common origin.</p>`,
      ["How do nasal polyps characteristically appear on examination?", "Smooth, rounded, semitransparent, glistening masses", ["Dry black crusts", "Ulcerated plaques", "Fluctuant gingival lesions"], "The deck emphasizes the smooth, rounded, glistening appearance."],
      ["Bilateral pale-gray glistening masses arise from the middle meatus. What is the most likely finding?", "Nasal polyps", ["Rhinitis medicamentosa", "Acute bacterial rhinosinusitis", "Turbinate edema alone"], "The location and characteristic appearance identify nasal polyps."], true),
      K("Symptoms and clinical diagnosis", `<p>Small polyps may be incidental. Large or extensive polyps cause chronic nasal congestion or obstruction, thick discharge, and reduced or absent smell. Postnasal drip, snoring, and sleep apnea may also occur.</p><p>The characteristic appearance can establish the diagnosis during examination with an otoscope and nasal speculum. Polyps may also appear on CT.</p>`,
      ["Which sensory change commonly occurs with extensive nasal polyps?", "Reduced or absent sense of smell", ["Hyperacusis", "Diplopia", "Loss of taste only"], "Anosmia accompanies obstructive polyp disease."],
      ["A patient has chronic nasal blockage, thick discharge, anosmia, and bilateral glistening masses. What is the best diagnosis?", "Nasal polyps", ["Seasonal allergic rhinitis alone", "Viral rhinosinusitis", "Rhinitis of pregnancy"], "The symptom pattern plus the visible masses is characteristic."], true)
    ]),

    O("02-polyp-associations", "2. Nasal Polyps: Associations and Samter Triad", [
      K("Epidemiology and associations", `<p>Nasal polyps occur two to four times more often in males and peak from ages 20 to 40. They are rare in children younger than 10.</p>${T(["Associated population or condition", "Lecture detail"], [["Asthma", "Polyps occur in 20–50% of patients"], ["Aspirin intolerance", "Found in 8–26% of patients with polyps"], ["Alcohol intolerance", "Found in 50% of patients with polyps"], ["Other associations", "Allergic or nonallergic rhinitis, rhinosinusitis, and food allergy"]])}`,
      ["In which age group does nasal-polyp onset peak?", "20 to 40 years", ["Birth to age 2", "Younger than 10", "Older than 80 only"], "The deck identifies ages 20–40 as the peak."],
      ["A child younger than 10 has a suspected nasal polyp. How common is that presentation according to the lecture?", "Rare", ["The usual peak", "More common than in adults", "Limited to females"], "Nasal polyps are rare before age 10."], true),
      K("Samter triad", `${M("Three components", "Adult-onset severe asthma + chronic rhinosinusitis with nasal polyps + aspirin or COX-1 NSAID intolerance")}<p>Examples of COX-1 inhibitors include naproxen, ibuprofen, and indomethacin. Ingestion may trigger sudden wheezing, dyspnea, cough, sneezing, congestion, or rhinorrhea within 30 minutes to 3 hours. The reaction can be life-threatening. Aspirin desensitization and a leukotriene antagonist such as montelukast may benefit selected patients.</p>`,
      ["Which three findings compose Samter triad?", "Asthma, chronic rhinosinusitis with nasal polyps, and aspirin or COX-1 NSAID intolerance", ["Asthma, urticaria, and penicillin allergy", "Polyps, dental caries, and anosmia", "Rhinitis, eczema, and food allergy"], "These three disorders define the triad."],
      ["An adult with severe asthma and nasal polyps wheezes soon after ibuprofen. Which association fits?", "Samter triad", ["Rhinitis medicamentosa", "Allergic fungal rhinosinusitis alone", "Viral rhinosinusitis"], "A COX-1 reaction completes the triad."], true)
    ]),

    O("03-polyp-treatment", "3. Nasal Polyps: Treatment", [
      K("Steroid therapy", `<p><strong>Intranasal steroids are first-line treatment.</strong> They reduce polyp size and improve congestion but do not eliminate the polyps. Examples include fluticasone, budesonide, and mometasone. If topical therapy fails, a short course of oral prednisone may be used.</p><p>The deck lists fluticasone 50 mcg as two sprays in each nostril once daily.</p>`,
      ["What is the treatment of choice for nasal polyps?", "Intranasal glucocorticoids", ["Oral antibiotics", "Topical decongestants indefinitely", "Antifungals"], "Intranasal steroids reduce polyp size."],
      ["A patient’s polyps remain symptomatic despite an intranasal steroid. What medication step is listed next?", "A short course of oral prednisone", ["Long-term oxymetazoline", "Immediate antibiotics", "Oral antihistamine alone"], "A short oral steroid course may follow ineffective topical therapy."], true),
      K("Surgery and recurrence", `<p>Persistent disease despite steroids requires ENT consultation. Polypectomy removes soft tissue with suction or a microdebrider. Endoscopic sinus surgery can remove larger polyps and enlarge sinus openings.</p><p>Polyps tend to recur. The notes report regrowth in up to 15% of people with a chronic nasal problem and recommend intranasal steroids after surgery to reduce recurrence.</p>`,
      ["When is surgical treatment considered for nasal polyps?", "When steroid treatment is ineffective", ["Before any medical therapy", "Only during viral rhinosinusitis", "Whenever a polyp is incidental"], "Refractory disease prompts ENT surgical evaluation."],
      ["A large obstructing polyp persists after steroid therapy. What is the next approach?", "ENT consultation for polypectomy or endoscopic sinus surgery", ["Continue a topical decongestant indefinitely", "Begin dental prophylaxis", "Use saline alone"], "Persistent obstructing polyps may require surgery."], true)
    ]),

    O("04-ar-pathogenesis", "4. Allergic Rhinitis: Definition and Pathogenesis", [
      K("Definition and immune response", `<p>Allergic rhinitis, or hay fever, is inflammation of the nasal mucosa caused by an <strong>IgE-mediated response</strong> to one or more allergens. Atopic patients make allergen-specific IgE. On re-exposure, IgE binds the allergen and triggers mast-cell release of histamine and leukotrienes in the respiratory mucosa.</p><p>Histamine increases vascular permeability, producing tissue swelling and dilated vessels, including swollen turbinates.</p>`,
      ["What immune mechanism causes allergic rhinitis?", "An IgE-mediated response to allergens", ["An invasive fungal infection", "A bacterial biofilm alone", "Alpha-receptor downregulation"], "Allergen-specific IgE triggers mediator release."],
      ["Re-exposure to an airborne allergen triggers mast-cell histamine release and turbinate swelling. What disorder is described?", "Allergic rhinitis", ["Rhinitis medicamentosa", "Acute bacterial rhinosinusitis", "Nasal trauma"], "The IgE and mast-cell pathway defines allergic rhinitis."], true),
      K("Common etiologies and patterns", `${T(["Pattern", "Typical triggers and features"], [["Perennial", "Dust, household mites, pet dander, mold spores, and cockroaches; congestion and postnasal drip predominate"], ["Seasonal", "Trees and shrubs in spring, grasses and plants in summer, ragweed and molds in fall; sneezing, watery rhinorrhea, itching, congestion, and watery eyes"], ["Environmental irritants", "Tobacco smoke and air pollution can increase symptoms"]])}<p>Persistent symptoms with seasonal exacerbations are more common than purely intermittent symptoms.</p>`,
      ["Which triggers commonly cause perennial allergic rhinitis?", "Dust mites, pet dander, mold spores, or cockroaches", ["Only flowering trees", "Bacteria in the sinuses", "COX-1 inhibitors only"], "Indoor allergens commonly drive year-round disease."],
      ["Symptoms recur each spring when trees flower. Which pattern is most likely?", "Seasonal allergic rhinitis", ["Perennial rhinitis", "Rhinitis medicamentosa", "Chronic bacterial infection"], "Reproducible pollen-season symptoms indicate seasonal disease."], true)
    ]),

    O("05-ar-risks", "5. Allergic Rhinitis: Associations and Risk Factors", [
      K("Associated atopic disorders", `<p>Allergic rhinitis is associated with other IgE-mediated inflammatory disorders, including <strong>asthma, atopic dermatitis, and nasal polyps</strong>. Allergic conjunctivitis may occur with bilateral eye itching, tearing, or burning. Up to 50% of patients with asthma also have allergic rhinitis.</p>`,
      ["Which conditions are associated with allergic rhinitis?", "Asthma, atopic dermatitis, and nasal polyps", ["Dental caries and pulpitis", "Osteomyelitis only", "Cavernous sinus thrombosis"], "They share an atopic or IgE-mediated pattern."],
      ["A patient with asthma and eczema develops recurrent sneezing and watery rhinorrhea. Which linked condition is likely?", "Allergic rhinitis", ["Rhinitis medicamentosa", "Bacterial rhinosinusitis", "Pott puffy tumor"], "Asthma and eczema are associated atopic disorders."], true),
      K("Additional risk factors", `<ul><li>Family history of atopy</li><li>Indoor allergen exposure</li><li>IgE above 100 units/mL before age 6 or allergen-specific IgE</li><li>Male sex, birth during pollen season, or firstborn status</li><li>Early antibiotic use</li><li>Maternal tobacco-smoke exposure during the first year</li></ul><p>The lecture notes that some listed factors remain under study.</p>`,
      ["Which history increases the risk of allergic rhinitis?", "A family history of atopy", ["No allergen exposure", "Prior polypectomy alone", "Use of sterile saline"], "A familial atopic tendency is a listed risk."],
      ["An infant had maternal tobacco-smoke exposure during the first year of life. How does the lecture classify this?", "A risk factor for allergic rhinitis", ["A diagnostic criterion for ABRS", "A treatment indication for surgery", "A cardinal CRS symptom"], "Early maternal-smoke exposure appears in the risk-factor list."], true)
    ]),

    O("06-ar-presentation", "6. Allergic Rhinitis: Symptoms and Exam", [
      K("Symptoms", `<p>The classic presentation consists of paroxysmal sneezing, clear watery rhinorrhea, nasal congestion or obstruction, and nasal itching. Other symptoms include postnasal drip, cough, irritability, fatigue, and itching of the palate or inner ear.</p><p>Associated allergic conjunctivitis causes bilateral itching, tearing, or burning of the eyes.</p>`,
      ["What is the classic symptom cluster of allergic rhinitis?", "Sneezing, watery rhinorrhea, nasal congestion, and nasal itching", ["Purulent drainage and neck stiffness", "Proptosis and gaze palsy", "Unilateral facial swelling only"], "The four symptoms form the classic presentation."],
      ["A patient has episodic sneezing, clear rhinorrhea, itchy nose, and bilateral itchy watery eyes. What is most likely?", "Allergic rhinitis with allergic conjunctivitis", ["Complicated ABRS", "Rhinitis medicamentosa", "Allergic fungal rhinosinusitis"], "The nasal and bilateral ocular symptoms support allergy."], true),
      K("Characteristic facial findings", `${T(["Finding", "Description"], [["Allergic shiners", "Infraorbital edema and dark lower-eyelid circles"], ["Dennie-Morgan lines", "Accentuated folds below the lower eyelids"], ["Allergic salute", "Upward rubbing of the nose, producing a transverse nasal crease"], ["Allergic facies", "High-arched palate and open-mouth breathing; longstanding mouth breathing may produce adenoid facies"]])}`,
      ["What produces the transverse nasal crease of allergic rhinitis?", "Repeated upward rubbing called the allergic salute", ["Sinus surgery", "Nasal irrigation", "Facial cellulitis"], "The nasal salute creates the transverse crease."],
      ["Dark lower-eyelid circles and infraorbital edema are noted in a patient with allergies. What are they called?", "Allergic shiners", ["Dennie-Morgan lines", "Pott puffy tumor", "Papilledema"], "Allergic shiners describe the dark infraorbital appearance."], true),
      K("Nasal, pharyngeal, and ear findings", `<ul><li>Pale blue or gray nasal mucosa</li><li>Boggy, edematous or hypertrophied turbinates</li><li>Clear nasal or posterior-oropharyngeal rhinorrhea</li><li>Posterior pharyngeal cobblestoning from lymphoid hyperplasia</li><li>Retracted tympanic membranes or serous middle-ear fluid when swelling causes eustachian-tube dysfunction</li></ul>`,
      ["Which nasal examination finding supports allergic rhinitis?", "Pale blue-gray mucosa with boggy turbinates", ["Black necrotic tissue", "A normal mucosa with no edema", "A gingival abscess"], "Pallor and boggy edema are characteristic."],
      ["A patient with chronic allergic symptoms has lymphoid hyperplasia of the posterior pharynx. What is this called?", "Cobblestoning", ["Allergic salute", "Samter triad", "Rhinitis medicamentosa"], "Cobblestoning describes the posterior pharyngeal change."], true)
    ]),

    O("07-ar-diagnosis", "7. Allergic Rhinitis: Diagnosis", [
      K("Clinical diagnosis", `<p>The diagnosis is clinical, based on characteristic symptoms, a suggestive history, and supportive examination findings. Seasonal disease may be identified by a reproducible yearly pattern. Episodic symptoms after animal, dust, home, or workplace exposure also provide useful clues.</p>`,
      ["How is allergic rhinitis usually diagnosed?", "Clinically from symptoms, exposure history, and examination", ["CT is required", "Fungal culture is required", "Nasal biopsy is required"], "The deck defines allergic rhinitis as a clinical diagnosis."],
      ["Symptoms appear around a cat and disappear during vacations. What part of the diagnosis does this support?", "A suggestive exposure history", ["A bacterial culture", "An objective CRS imaging finding", "A surgical indication"], "Reproducible exposure-response patterns support the clinical diagnosis."], true),
      K("Allergy testing", `<p>Skin-prick testing and allergen-specific serum IgE testing confirm sensitization to a specific allergen. Testing is not always necessary before presumptive diagnosis and conservative treatment. Its main role is to identify patients who may benefit from allergen immunotherapy.</p>`,
      ["What do skin-prick and serum-specific IgE tests establish?", "Sensitization to a specific allergen", ["Bacterial extension beyond the sinus", "A nasal-polyp biopsy", "Rhinitis medicamentosa"], "These tests confirm allergen sensitization."],
      ["A patient responds poorly to empiric therapy and may pursue immunotherapy. What diagnostic step is most useful?", "Allergy testing", ["Routine sinus CT for every patient", "Dental radiography", "Fungal surgery"], "Testing helps select allergens for immunotherapy."], true)
    ]),

    O("08-ar-treatment", "8. Allergic Rhinitis: Treatment Approach", [
      K("Three treatment components", `${T(["Component", "Approach"], [["Environmental control", "Avoid the identified allergen and reduce exposure"], ["Pharmacotherapy", "Use intranasal steroids, antihistamines, or selected adjuncts for symptom control"], ["Allergen immunotherapy", "Specialist-directed desensitization when appropriate"]])}<p>Seasonal control includes closing windows and limiting outdoor exposure during the relevant pollen season. Perennial control includes lowering humidity below 50%, washing linens in hot water, encasing bedding, reducing carpets, and avoiding the triggering pet.</p>`,
      ["What are the three main components of allergic-rhinitis treatment?", "Allergen avoidance, pharmacotherapy, and allergen immunotherapy", ["Antibiotics, surgery, and CT", "Steroids, antifungals, and biopsy", "Observation, drainage, and oxygen"], "The deck organizes treatment into these three components."],
      ["A patient has a dust-mite allergy. Which measure follows environmental-control guidance?", "Wash linens in hot water and encase bedding", ["Keep humidity above 70%", "Use oxymetazoline indefinitely", "Begin antibiotics"], "Bedding control and reduced humidity limit indoor allergens."], true),
      K("Treatment by symptom pattern", `${T(["Pattern", "General approach"], [["Persistent daily or moderate-to-severe", "Intranasal glucocorticoid"], ["Intermittent", "Oral or intranasal antihistamine"], ["Chronic daily", "Intranasal steroid, with an oral antihistamine if needed"]])}<p>Persistent symptoms occur more than four days per week and for more than four weeks. Intermittent symptoms occur less than four days per week or for less than four weeks. Intranasal steroids may take one to two weeks for relief, while antihistamines act more quickly.</p>`,
      ["What is the preferred pharmacologic treatment for persistent or moderate-to-severe allergic rhinitis?", "An intranasal glucocorticoid", ["A long-term topical decongestant", "An antibiotic", "An oral antifungal"], "Nasal steroids are the most effective therapy for this symptom pattern."],
      ["A patient has sneezing and itching two days per week without congestion and wants rapid relief. Which approach fits?", "An oral or intranasal antihistamine", ["Chronic prednisone", "Endoscopic sinus surgery", "High-dose Augmentin"], "Intermittent symptoms respond quickly to antihistamines."], true),
    ]),

    O("09-nasal-steroids", "9. Nasal Glucocorticoids", [
      K("Mechanism and clinical effect", `<p>Intranasal glucocorticoids bind intracellular glucocorticoid receptors in inflammatory-cell cytoplasm. They reduce mucosal-cell responses to allergens, increase anti-inflammatory protein production, and suppress local cytokine release.</p><p>They relieve congestion, discharge, sneezing, itching, and postnasal drip more effectively than oral antihistamines. Relief usually takes one to two weeks.</p>`,
      ["How do nasal glucocorticoids reduce allergic inflammation?", "They bind intracellular receptors and downregulate inflammatory responses", ["They eradicate bacteria", "They desensitize alpha receptors", "They dissolve polyps immediately"], "The deck describes receptor binding and reduced inflammatory signaling."],
      ["A patient expects immediate relief after the first nasal-steroid dose. What counseling matches the lecture?", "Meaningful relief may take one to two weeks", ["Relief always occurs in 15 minutes", "The drug works only after surgery", "Stop after one dose"], "Nasal glucocorticoids have a delayed clinical effect."], true),
      K("Agents with minimal systemic bioavailability", `${T(["Second-generation agent", "Systemic availability"], [["Fluticasone propionate", "Less than 1% or undetectable"], ["Mometasone", "Less than 1% or undetectable"], ["Ciclesonide", "Less than 1% or undetectable"]])}<p>Other listed agents include budesonide, beclomethasone, and triamcinolone. The remaining first-generation agents have systemic bioavailability of 10–50%.</p>`,
      ["Which nasal steroids have limited to undetectable systemic bioavailability?", "Fluticasone, mometasone, and ciclesonide", ["Budesonide, beclomethasone, and triamcinolone only", "Prednisone and methylprednisolone", "Oxymetazoline and phenylephrine"], "The deck marks these three as second-generation agents."],
      ["A clinician wants a nasal steroid with less than 1% or undetectable systemic effects. Which is listed?", "Mometasone", ["Beclomethasone", "Prednisone", "Ipratropium"], "Mometasone is one of the marked second-generation options."], true)
    ]),

    O("10-steroid-effects", "10. Nasal Glucocorticoid Adverse Effects", [
      K("Local adverse effects", `<p>Potential local effects include mucosal drying, burning, irritation, medication runoff into the throat, epistaxis, and nasal septal perforation. Direct the spray toward the ipsilateral ear rather than the septum and keep the head slightly forward.</p><p>For traces of blood, the notes recommend pausing treatment on the affected side for a few days and then restarting. Significant epistaxis requires discontinuation, with azelastine as an alternative.</p>`,
      ["Which adverse effects are specific concerns with nasal glucocorticoid sprays?", "Epistaxis and nasal septal perforation", ["Dental fracture and pulpitis", "Cavernous sinus thrombosis", "Fungal invasion"], "These local effects are unique concerns with intranasal delivery."],
      ["A patient repeatedly sprays toward the septum and develops significant epistaxis. What should happen?", "Discontinue the spray and consider azelastine", ["Double the dose", "Add oxymetazoline indefinitely", "Begin Augmentin"], "The notes recommend stopping treatment for significant bleeding."], true),
      K("Long-term systemic concerns", `<p>General glucocorticoid concerns include adrenal suppression, slowed growth in children, reduced bone mineral density, glaucoma, and cataracts. The risk with nasal sprays appears small because the doses are low, especially with agents that have little systemic bioavailability.</p>`,
      ["Why is the systemic risk from nasal glucocorticoids generally small?", "The intranasal doses and systemic bioavailability are low", ["They contain no glucocorticoid", "They are antibiotics", "They never contact mucosa"], "Low exposure limits systemic effects."],
      ["Which potential long-term concern should still be recognized with glucocorticoid preparations?", "Adrenal suppression", ["Tooth avulsion", "Bacterial biofilm", "Rhinitis medicamentosa after one dose"], "Adrenal suppression appears in the lecture's long-term concern list."], true)
    ]),

    O("11-antihistamines", "11. Antihistamines", [
      K("First- and second-generation agents", `${T(["Generation", "Agents"], [["Second generation", "Cetirizine, levocetirizine, loratadine, fexofenadine"], ["First generation", "Diphenhydramine, chlorpheniramine, hydroxyzine"]])}<p>Second-generation agents are preferred because they cause less sedation and fewer anticholinergic and neurologic effects. They also do not develop the tolerance described with first-generation agents.</p>`,
      ["Which drugs are second-generation antihistamines?", "Cetirizine, levocetirizine, loratadine, and fexofenadine", ["Diphenhydramine, chlorpheniramine, and hydroxyzine", "Fluticasone, mometasone, and ciclesonide", "Phenylephrine and pseudoephedrine"], "These four comprise the second-generation list."],
      ["A patient needs an oral antihistamine with less sedation. Which is preferred?", "Loratadine", ["Diphenhydramine", "Hydroxyzine", "Chlorpheniramine"], "Loratadine is a preferred second-generation option."], true),
      K("Benefits, limitations, and adverse effects", `<p>H1 blockade can reduce itching, sneezing, and rhinorrhea within about one hour, but oral antihistamines treat nasal congestion less effectively than nasal steroids. First-generation drugs are lipophilic, cross the blood-brain barrier, and can cause sedation plus cognitive and motor impairment. Very young children may develop paradoxical agitation.</p><p>Anticholinergic effects produce the pattern: hot, flushed, dry, confused, and blurred vision.</p>`,
      ["What major adverse effect distinguishes first-generation antihistamines?", "Sedation with cognitive and motor impairment", ["Nasal septal perforation", "Bacterial resistance", "Pott puffy tumor"], "Blood-brain barrier penetration drives these effects."],
      ["A young child becomes agitated after a first-generation antihistamine. How does the lecture explain this?", "Paradoxical agitation can occur", ["It proves bacterial sinusitis", "It indicates Samter triad", "It is a steroid effect"], "The notes identify paradoxical agitation in very young children."], true)
    ]),

    O("12-ar-adjuncts", "12. Allergic Rhinitis Adjuncts", [
      K("Local adjunct therapies", `${T(["Therapy", "Best use or caution"], [["Intranasal cromolyn", "Begin well before allergen exposure, up to four weeks prior"], ["Intranasal ipratropium", "Helps significant rhinorrhea"], ["Nasal saline", "Spray or irrigation washes allergens from mucosa"], ["Intranasal azelastine", "Rapid relief of itching, sneezing, rhinorrhea, and congestion"]])}`,
      ["Which adjunct specifically helps prominent rhinorrhea?", "Intranasal ipratropium", ["Oral prednisone for every case", "Augmentin", "Endoscopic surgery"], "The anticholinergic spray targets rhinorrhea."],
      ["A patient knows pollen exposure will begin in one month. Which preventive adjunct can start now?", "Intranasal cromolyn", ["Doxycycline", "Oxymetazoline for the full month", "Oral antifungal therapy"], "Cromolyn must begin well before exposure."], true),
      K("Leukotriene modifier and decongestants", `<p>Montelukast may improve rhinorrhea, sneezing, and congestion but is less effective than intranasal steroids. Because of its boxed warning for mood changes and suicidality, reserve it for patients who cannot tolerate nasal sprays or antihistamines and stop it if mood effects occur.</p><p>Oral phenylephrine or pseudoephedrine may reduce congestion but can raise blood pressure and cause irritability, insomnia, and headache. Avoid them in hypertension or cardiovascular disease. Topical decongestants should not exceed three consecutive days.</p>`,
      ["When should montelukast be considered for allergic rhinitis?", "When nasal sprays and antihistamines cannot be tolerated", ["As routine first-line therapy", "For every mild intermittent case", "Only for bacterial infection"], "Its lower efficacy and boxed warning limit its role."],
      ["A patient with hypertension asks for pseudoephedrine. What concern does the lecture identify?", "It can elevate blood pressure and should be avoided", ["It causes nasal polyps", "It is an antibiotic", "It causes dental avulsion"], "Oral decongestants have cardiovascular adverse effects."], true)
    ]),

    O("13-rhinitis-medicamentosa", "13. Rhinitis Medicamentosa", [
      K("Rebound congestion cycle", `<p>Rhinitis medicamentosa is severe rebound nasal congestion caused by downregulation of alpha-adrenergic receptors. It usually follows three to seven days of a topical nasal decongestant such as oxymetazoline. The spray temporarily relieves the congestion it causes, leading to escalating use and dependency.</p><p>Prevention and management center on limiting topical decongestants to no more than three consecutive days and ending the offending spray cycle.</p>`,
      ["What causes rhinitis medicamentosa?", "Prolonged topical nasal-decongestant use with alpha-receptor downregulation", ["An IgE response to pollen", "A bacterial biofilm", "A nasal glucocorticoid used correctly"], "Alpha-receptor downregulation produces rebound congestion."],
      ["A patient uses oxymetazoline for a week and now needs increasing doses for congestion. What is the diagnosis?", "Rhinitis medicamentosa", ["Seasonal allergic rhinitis", "Acute viral rhinosinusitis", "Allergic fungal rhinosinusitis"], "Use beyond the recommended duration creates the rebound cycle."], true),
      K("Culprit agents and safer limit", `<p>Topical phenylephrine, oxymetazoline, xylometazoline, and naphazoline can cause this disorder. The lecture's practical limit is <strong>no more than three consecutive days</strong>.</p>`,
      ["How long may a topical nasal decongestant be used before rebound risk rises?", "No more than three consecutive days", ["Two weeks", "One month", "Indefinitely"], "The deck uses a three-day limit."],
      ["Which drug can produce rebound congestion when overused?", "Oxymetazoline", ["Nasal saline", "Amoxicillin-clavulanate", "Cromolyn"], "Oxymetazoline is the lecture's key example."], true)
    ]),

    O("14-sinus-pathophysiology", "14. Sinus Disease Pathophysiology", [
      K("Normal clearance", `<p>Sinuses contain sterile mucus and ciliated mucosa. Cilia transport mucus and trapped contaminants toward the ostia, the small channels that drain unidirectionally into the nose. Partial ostial blockage causes mucus stasis.</p><p>Effective drainage depends on ciliary action, mucus viscosity, ostial size, and normal structural orientation.</p>`,
      ["What is the role of sinus cilia?", "Move mucus and contaminants toward the ostia", ["Produce IgE", "Enlarge polyps", "Downregulate alpha receptors"], "Cilia act as a coordinated clearance system."],
      ["Even partial obstruction of a sinus ostium produces what key effect?", "Stasis of mucus flow", ["Immediate anosmia only", "Improved drainage", "Reduced mucus viscosity"], "Ostial obstruction impairs clearance."], true),
      K("Three mechanisms of infection", `${T(["Mechanism", "Examples"], [["Ostial obstruction, most common", "Viral edema, chemical irritation, allergy, trauma, polyps, foreign body, or deviated septum"], ["Increased mucus viscosity", "Infection, autoimmune or systemic inflammation, medication, or dehydration"], ["Impaired ciliary action", "Large bacterial inoculum, cystic fibrosis or genetic dysfunction, hypoxia, or cold dry air"]])}`,
      ["What is the most common mechanism leading to sinus infection?", "Obstruction of the sinus ostium", ["Increased smell", "Reduced IgE", "Middle-ear fluid"], "The deck identifies ostial obstruction as most common."],
      ["A patient with cystic fibrosis has thick mucus that cilia cannot propel. Which mechanisms are affected?", "Mucus viscosity and ciliary clearance", ["Allergen immunotherapy", "Alpha-receptor sensitivity", "Dental pulp perfusion"], "Thick mucus and ineffective cilia promote stasis."], true)
    ]),

    O("15-rhinosinusitis-duration", "15. Rhinosinusitis by Duration", [
      K("Timing categories", `${T(["Classification", "Duration"], [["Acute", "Less than 4 weeks"], ["Subacute", "4–11 weeks"], ["Chronic", "12 weeks or longer"], ["Recurrent", "At least 4 acute episodes per year, each lasting 7–10 days, with complete interim resolution"]])}`,
      ["How long must symptoms persist to meet the chronic timing category?", "At least 12 weeks", ["Less than 4 weeks", "Exactly 7 days", "4–11 weeks"], "Twelve weeks is the chronic threshold."],
      ["A patient has five 8-day episodes in one year and is symptom-free between them. How is this classified?", "Recurrent acute rhinosinusitis", ["Chronic rhinosinusitis", "Subacute rhinosinusitis", "One prolonged viral episode"], "Four or more discrete episodes with interval resolution define recurrent disease."], true),
      K("Acute disease framework", `<p>Rhinosinusitis is inflammation of the nasal cavity and paranasal sinuses. Viral disease is the most common acute etiology. Only 0.5–2% of adults with acute viral rhinosinusitis progress to acute bacterial rhinosinusitis.</p><p>Bacterial disease is uncomplicated when confined to the nasal cavity and sinuses and complicated when it extends beyond them.</p>`,
      ["What is the most common cause of acute rhinosinusitis?", "Viral infection", ["Bacterial infection", "Invasive fungus", "Dental trauma"], "Viral illness causes most acute cases."],
      ["ABRS extends into the orbit. How is it classified?", "Complicated bacterial rhinosinusitis", ["Uncomplicated bacterial rhinosinusitis", "Seasonal rhinitis", "Subacute viral rhinosinusitis"], "Extension outside the sinuses and nasal cavity defines complicated disease."], true)
    ]),

    O("16-viral-bacterial", "16. Viral vs Bacterial Rhinosinusitis", [
      K("Timing and clinical course", `${T(["Feature", "Viral", "Bacterial"], [["Typical duration", "Resolves in 7–10 days", "Persists beyond 10 days without improvement"], ["Course", "Self-limited URI-like illness", "May show double worsening after initial improvement"], ["Fever", "If present, early and usually resolves in 24–48 hours", "May be severe, above 102°F for 3–4 consecutive days"], ["Drainage", "May change from watery to purulent and back", "Persistent purulent drainage"]])}<p>Severe symptoms or immunocompromise may support bacterial disease before day 10.</p>`,
      ["Which time course most strongly supports acute bacterial rhinosinusitis?", "Symptoms beyond 10 days without improvement", ["Symptoms improving by day 5", "One day of clear rhinorrhea", "Intermittent pollen symptoms"], "Persistence beyond ten days is a key distinction."],
      ["Symptoms improve, then worsen again with purulent drainage and facial pain. What pattern is this?", "Double worsening suggesting bacterial rhinosinusitis", ["Expected viral resolution", "Rhinitis medicamentosa", "Perennial allergy"], "Biphasic worsening points toward ABRS."], true),
      K("Shared and distinguishing findings", `<p>Both can produce congestion, decreased smell, sneezing, facial pain or pressure that worsens with bending forward, headache, throat discomfort, or cough. Viral and bacterial disease may both have sinus tenderness and colored drainage, so purulence alone does not establish bacterial disease.</p><p>Bacterial minor symptoms include otalgia, halitosis, dental pain, and fatigue.</p>`,
      ["Can purulent drainage alone distinguish viral from bacterial rhinosinusitis?", "No, it can occur in both", ["Yes, it always proves bacterial disease", "Yes, it always proves viral disease", "Only after CT"], "Viral drainage may become purulent during the illness."],
      ["A patient has facial pain without any nasal drainage. Is that sufficient for an ARS diagnosis?", "No", ["Yes, it confirms ABRS", "Yes, it confirms viral rhinosinusitis", "Only in children"], "The notes state that facial pain without drainage is insufficient."], true),
      K("Treatment contrast", `<p>Acute viral rhinosinusitis receives supportive care because no treatment shortens the illness. Options include antipyretics or analgesics, sterile saline irrigation, intranasal glucocorticoids, and selected short-term symptom therapies.</p><p>ABRS also starts with supportive care. Adults with reliable follow-up, no anatomic spread risk, and no immunocompromise or major comorbidity may undergo seven days of watchful waiting after diagnosis. Children with ABRS should receive immediate antibiotics.</p>`,
      ["How is acute viral rhinosinusitis treated?", "Supportive and symptom-directed care", ["Routine antibiotics", "Immediate sinus surgery", "Antifungal therapy"], "The viral illness is self-limited."],
      ["Which ABRS patient should receive immediate antibiotics rather than adult watchful waiting?", "A child with ABRS", ["Every healthy adult with good follow-up", "A patient with one day of clear drainage", "A patient with seasonal itching only"], "The lecture prefers immediate antibiotics for children."], true)
    ]),

    O("17-pathogens", "17. Viral and Bacterial Pathogens", [
      K("Viral causes", `<p>The principal viral causes are <strong>rhinovirus, influenza virus, and parainfluenza virus</strong>. Viral inoculation occurs through direct contact with the conjunctiva or nasal mucosa. Replication becomes detectable in nasal secretions within 8–10 hours, and symptoms usually begin within one day.</p>`,
      ["Which viruses commonly cause acute viral rhinosinusitis?", "Rhinovirus, influenza virus, and parainfluenza virus", ["Streptococcus, Haemophilus, and Moraxella", "Aspergillus only", "MRSA only"], "These are the three viral pathogens listed."],
      ["A common-cold illness spreads from the nasal mucosa into the sinuses. Which etiology is most likely?", "A respiratory virus such as rhinovirus", ["An anaerobic dental infection", "A bacterial biofilm", "Aspirin intolerance"], "Viral URIs are the usual starting point for AVRS."], true),
      K("Bacterial causes and special settings", `<p>The most common ABRS bacteria are <em>Streptococcus pneumoniae</em>, <em>Haemophilus influenzae</em>, and <em>Moraxella catarrhalis</em>. <em>S. pneumoniae</em> plus <em>H. influenzae</em> account for about 75% of cases.</p><ul><li><em>S. aureus</em>: MRSA colonization or IV drug use</li><li>Anaerobes: extension from a dental infection</li><li>Nosocomial gram-negative organisms: ICU admission, intubation, or nasogastric tubes</li></ul>`,
      ["Which bacteria cause most routine ABRS?", "S. pneumoniae, H. influenzae, and M. catarrhalis", ["Rhinovirus, influenza, and parainfluenza", "Only S. aureus", "Only anaerobes"], "These are the three leading bacterial pathogens."],
      ["Foul-smelling sinus drainage accompanies a dental-root infection. Which organisms require coverage?", "Anaerobes", ["Rhinovirus", "Influenza virus", "Only MRSA"], "Dental extension suggests anaerobic disease."], true)
    ]),

    O("18-abrs-antibiotics", "18. Bacterial Rhinosinusitis Antibiotics", [
      K("First-line populations", `${T(["Population", "Drug choice and deck dosing"], [["Adults younger than 65, including pregnancy", "Amoxicillin-clavulanate 875/125 mg PO twice daily for 5–7 days"], ["Children", "Amoxicillin-clavulanate 45 mg/kg/day PO in 2 doses for 10 days"]])}<p>The addition of clavulanate expands coverage for ampicillin-resistant <em>H. influenzae</em> and <em>M. catarrhalis</em>.</p>`,
      ["What is the antibiotic of choice for routine ABRS in adults younger than 65, including pregnancy?", "Amoxicillin-clavulanate", ["Azithromycin", "Trimethoprim-sulfamethoxazole", "Fluconazole"], "The deck names Augmentin first line."],
      ["A child is diagnosed with ABRS. Which first-line drug is listed?", "Amoxicillin-clavulanate", ["Doxycycline", "Azithromycin", "No antibiotic under any circumstance"], "The pediatric first-line agent is also Augmentin."], true),
      K("Penicillin allergy", `${T(["Population", "Alternative"], [["Adult", "Doxycycline 100 mg PO twice daily for 5–7 days"], ["Adult", "Cefixime 400 mg daily with or without clindamycin 300 mg every 6 hours for 5–7 days"], ["Child with mild delayed penicillin hypersensitivity", "Cefdinir 14 mg/kg/day in 2 doses for 10 days"], ["Child with penicillin anaphylaxis", "Levofloxacin 10–20 mg/kg/day in 2 doses"]])}<p>Avoid doxycycline in pregnancy. The notes state that macrolides and trimethoprim-sulfamethoxazole are not recommended empirically because of pneumococcal resistance.</p>`,
      ["Which adult ABRS alternative is listed for penicillin allergy?", "Doxycycline", ["Azithromycin as preferred empiric therapy", "Trimethoprim-sulfamethoxazole", "Fluticasone alone"], "Doxycycline is the listed adult alternative."],
      ["A child had a mild delayed penicillin rash and now needs ABRS treatment. Which drug is listed?", "Cefdinir", ["Doxycycline", "Montelukast", "Cromolyn"], "Cefdinir is the pediatric option for mild delayed hypersensitivity."], true),
      K("High resistance risk, dental source, and failure", `<p>Use high-dose amoxicillin-clavulanate for age under 2 or over 65, recent hospitalization or antibiotics, daycare, inadequate pneumococcal immunization, immunocompromise, multiple comorbidities, or severe symptoms. The deck lists 2000/125 mg ER twice daily for adults and 90 mg/kg/day in two doses for children.</p><p>For a dental source with foul discharge, use Augmentin or cefpodoxime plus metronidazole. If the patient worsens after 2–3 days or fails to improve after 7 days, switch agents, consider contrast CT, and consult ENT if nonresponse continues.</p>`,
      ["Who requires high-dose Augmentin for ABRS?", "A patient at high risk for penicillin-resistant S. pneumoniae", ["Every patient with one day of symptoms", "Only patients with allergic rhinitis", "Only patients using saline"], "Resistance-risk features trigger high-dose therapy."],
      ["An adult worsens three days after starting standard Augmentin. What should be considered?", "Switch antibiotics and evaluate for failure or complications", ["Continue unchanged indefinitely", "Diagnose seasonal allergy", "Start aspirin desensitization"], "Worsening after 2–3 days meets treatment-failure guidance."], true)
    ]),

    O("19-abrs-complications", "19. Bacterial Rhinosinusitis Complications", [
      K("Sites and named complications", `<p>Complicated ABRS extends beyond the nasal cavity and sinuses into the orbit, central nervous system, bone, or surrounding tissue. Named complications include preseptal cellulitis, orbital cellulitis or abscess, osteomyelitis, cavernous sinus thrombosis, meningitis, and intracranial extension.</p><p>Pott puffy tumor is osteomyelitis associated with frontal sinusitis.</p>`,
      ["Which complication is specifically associated with frontal sinusitis?", "Pott puffy tumor", ["Rhinitis medicamentosa", "Allergic salute", "Samter triad"], "The notes identify it as a frontal-sinusitis complication."],
      ["A sinus infection extends into the orbit. How should it be classified?", "Complicated ABRS", ["Uncomplicated ABRS", "Viral rhinitis", "Perennial allergy"], "Orbital spread means the disease is no longer confined to the sinuses."], true),
      K("Emergency warning signs", `<ul><li>Severe persistent headache</li><li>Periorbital edema, inflammation, or erythema</li><li>Diplopia or impaired vision</li><li>Abnormal extraocular movements, proptosis, or pain with eye movement</li><li>Cranial-nerve palsy</li><li>Altered mental status</li><li>Neck stiffness, meningeal signs, or papilledema</li></ul>`,
      ["Which finding suggests orbital spread of ABRS?", "Proptosis with pain on eye movement", ["Isolated nasal itching", "Clear rhinorrhea for two days", "A transverse nasal crease"], "Proptosis and painful eye movement are emergency signs."],
      ["A patient with sinusitis develops altered mental status and neck stiffness. What should be suspected?", "Intracranial or meningeal extension", ["Uncomplicated viral illness", "Intermittent allergic rhinitis", "Rhinitis medicamentosa"], "Neurologic and meningeal signs suggest extension."], true),
      K("Hospitalization and referral", `<p>Complicated disease is an emergency requiring hospital evaluation and otolaryngology involvement, with ophthalmology or neurosurgery as needed. Hospitalize for persistent fever above 102°F despite outpatient antibiotics, facial cellulitis, proptosis, visual or gaze changes, abscess, cavernous-sinus involvement, mental-status change, meningismus, or immunocompromise.</p><p>Outpatient ENT referral fits ABRS that fails one or two oral antibiotic courses. Persistent symptoms for 4–12 weeks warrant nasal endoscopy and CT. Do not delay emergency transfer for outpatient referral when complication signs are present.</p>`,
      ["What is the disposition for ABRS with proptosis and visual change?", "Hospital emergency evaluation with ENT involvement", ["Routine follow-up in several months", "Allergen avoidance only", "Watchful waiting at home"], "Orbital warning signs require urgent care."],
      ["ABRS remains unresolved after two oral antibiotic courses without emergency signs. What is appropriate?", "Outpatient ENT referral", ["No further evaluation", "Aspirin desensitization", "Long-term topical decongestant"], "Failure of one or two courses is a referral indication."], true)
    ]),

    O("20-crs-subtypes", "20. Chronic Rhinosinusitis Subtypes", [
      K("Definition and three syndromes", `<p>Chronic rhinosinusitis is inflammation of the paranasal sinuses and nasal passages lasting <strong>12 weeks or longer</strong>. Chronic disease is primarily an ongoing inflammatory process rather than a simple acute infection.</p>${T(["Subtype", "Approximate share"], [["CRS without nasal polyps", "60–65%; most common"], ["CRS with nasal polyps", "20–33%"], ["Allergic fungal rhinosinusitis", "Less than 5%"]])}`,
      ["What are the three clinical subtypes of CRS?", "CRS without polyps, CRS with polyps, and allergic fungal rhinosinusitis", ["Viral, bacterial, and dental", "Seasonal, perennial, and medicamentosa", "Acute, subacute, and recurrent"], "These are the three chronic syndromes in the deck."],
      ["Symptoms and inflammation have persisted for 14 weeks. Which timing category applies?", "Chronic rhinosinusitis", ["Acute rhinosinusitis", "Subacute rhinosinusitis", "One recurrent episode"], "CRS begins at 12 weeks."], true),
      K("Subtype clues", `<ul><li><strong>Without polyps:</strong> no bilateral middle-meatus polyposis; this is the most common form.</li><li><strong>With polyps:</strong> bilateral polyps in the middle meatus on anterior rhinoscopy or endoscopy; associated with Samter triad.</li><li><strong>Allergic fungal:</strong> immunocompetent patient with IgE-mediated fungal allergy and fungi in eosinophilic mucin.</li></ul>`,
      ["Which CRS subtype requires an immunocompetent patient with IgE-mediated fungal allergy?", "Allergic fungal rhinosinusitis", ["CRS without polyps", "Routine acute bacterial rhinosinusitis", "Rhinitis medicamentosa"], "Immunocompetence and fungal allergy define AFRS."],
      ["Bilateral middle-meatus polyps accompany chronic symptoms. Which subtype is present?", "CRS with nasal polyps", ["CRS without polyps", "Viral rhinosinusitis", "Subacute rhinosinusitis"], "Bilateral polyposis defines the polyp subtype."], true)
    ]),

    O("21-crs-comparison", "21. Chronic Rhinosinusitis Subtype Comparison", [
      K("Pathophysiology", `${T(["Subtype", "Underlying process"], [["Without polyps", "Ostial obstruction and ABRS progress to chronic inflammation; bacterial biofilm may persist"], ["With polyps", "Polyp tissue contains high T-helper-cell activity and histamine, creating local inflammation"], ["Allergic fungal", "Intense allergic inflammation targets colonizing, noninvasive fungi"]])}<p>Ostial obstruction, mucus stagnation, and chronic inflammation are common themes across CRS.</p>`,
      ["What process characterizes CRS without nasal polyps?", "Unresolved obstruction and infection progress to chronic inflammation, often with biofilm", ["Invasive fungus in every case", "Alpha-receptor downregulation", "Aspirin ingestion alone"], "The no-polyp subtype often follows failed resolution of acute disease."],
      ["An immunocompetent patient reacts to colonizing noninvasive fungus. Which subtype fits?", "Allergic fungal rhinosinusitis", ["CRS without polyps", "Viral rhinosinusitis", "Rhinitis medicamentosa"], "AFRS is an allergic response rather than tissue invasion."], true),
      K("Risk factors and associations", `${T(["Factor", "Important subtype link"], [["Untreated ABRS, smoking, irritants, anatomic blockage", "CRS generally"], ["Asthma or aspirin-exacerbated respiratory disease", "CRS with polyps"], ["Defective mucociliary clearance or cystic fibrosis", "Increased CRS risk, especially polyposis"], ["Immunodeficiency", "CRS risk, but not AFRS because AFRS requires immunocompetence"], ["Frequent viral URIs", "May contribute particularly to CRS without polyps"]])}<p>All children with nasal polyposis should undergo evaluation for cystic fibrosis.</p>`,
      ["Which association is especially linked to CRS with nasal polyps?", "Asthma or aspirin-exacerbated respiratory disease", ["Topical decongestant use only", "Dental fracture", "Isolated viral exposure"], "Asthma and AERD are important polyp associations."],
      ["A child is diagnosed with nasal polyposis. What associated condition should be evaluated?", "Cystic fibrosis", ["Pulpitis", "Gingival hyperplasia", "Tinnitus"], "The notes explicitly recommend CF evaluation in this setting."], true),
      K("Clinical and diagnostic differences", `<p>All three types can share the four cardinal CRS symptoms. Subtyping depends on examination, imaging, and selected tissue or laboratory findings.</p>${T(["Subtype", "Diagnostic clue"], [["Without polyps", "CRS criteria without bilateral polyposis"], ["With polyps", "Bilateral nasal polyps"], ["Allergic fungal", "Polypoid thickening or opacified sinuses with characteristic hyperdensities, fungal allergy, and fungi in eosinophilic mucin"]])}<p>AFRS surgery supplies tissue to confirm eosinophils and fungal elements and to exclude invasive fungal disease.</p>`,
      ["What examination finding distinguishes CRS with polyps?", "Bilateral nasal polyposis", ["Clear rhinorrhea alone", "Unilateral itching", "Normal nasal examination"], "Bilateral polyps identify this subtype."],
      ["CT shows opacified sinuses with hyperdensities, and eosinophilic mucin contains fungal hyphae. Which subtype fits?", "Allergic fungal rhinosinusitis", ["CRS without polyps", "Acute viral rhinosinusitis", "Rhinitis medicamentosa"], "The imaging and fungal-allergy evidence support AFRS."], true)
    ]),

    O("22-crs-diagnosis", "22. Chronic Rhinosinusitis Diagnosis", [
      K("Four cardinal symptoms", `${M("Adults", "Nasal congestion or obstruction + facial pain or pressure + purulent anterior or posterior drainage + reduced or absent smell")}<p>In children, cough replaces reduced smell as the fourth cardinal symptom. Congestion is usually bilateral. Thick yellow, green, or brown mucus is more typical of recurrent ABRS or allergic fungal disease than routine CRS.</p>`,
      ["What are the four adult cardinal symptoms of CRS?", "Nasal obstruction, facial pressure, purulent drainage, and reduced smell", ["Sneezing, itching, fever, and rash", "Proptosis, diplopia, palsy, and meningismus", "Otalgia, tinnitus, vertigo, and hearing loss"], "These are the diagnostic symptom anchors."],
      ["Which symptom replaces reduced smell in the pediatric cardinal-symptom set?", "Cough", ["Tinnitus", "Dental pain", "Diplopia"], "The notes specify cough for children."], true),
      K("Complete diagnostic criteria", `<p>CRS requires at least <strong>two cardinal symptoms for 12 weeks or longer despite medical management</strong>, plus objective evidence of inflammation.</p>${T(["Objective evidence", "Finding"], [["Rhinoscopy or endoscopy", "Purulent, not clear, mucus or edema in the middle meatus or ethmoid region"], ["Rhinoscopy or endoscopy", "Polyps in the nasal cavity or middle meatus"], ["Imaging", "Mucosal thickening or partial or complete sinus opacification"]])}`,
      ["What combination establishes CRS?", "At least two cardinal symptoms for 12 weeks plus objective inflammation", ["One day of congestion alone", "Purulence without symptoms", "A positive allergy test alone"], "Both chronic symptoms and objective inflammatory evidence are required."],
      ["A patient has congestion and reduced smell for 13 weeks, but no inflammatory finding on exam or imaging. Are CRS criteria complete?", "No, objective inflammation is also required", ["Yes, duration alone is sufficient", "Yes, one symptom is enough", "Only if fever is present"], "The diagnosis requires objective evidence."], true)
    ]),

    O("23-crs-treatment", "23. Chronic Rhinosinusitis Treatment", [
      K("Treatment goals and lifestyle", `<p>CRS usually cannot be cured, so treatment aims to reduce symptoms and improve quality of life. Goals are to control mucosal inflammation and edema, maintain sinus ventilation and drainage, treat colonizing or infecting organisms when present, and reduce acute exacerbations.</p><p>Smoking cessation improves symptoms and quality of life, reduces systemic-steroid use, and improves outcomes after endoscopic sinus surgery.</p>`,
      ["What are the main goals of CRS therapy?", "Control inflammation, preserve drainage, treat organisms when present, and reduce exacerbations", ["Guarantee a permanent cure", "Use antibiotics in every subtype", "Avoid all saline"], "CRS treatment focuses on control and function."],
      ["Which lifestyle change improves CRS symptoms and surgical outcomes?", "Smoking cessation", ["Increasing tobacco exposure", "Long-term topical decongestants", "Avoiding all nasal saline"], "The deck identifies smoking cessation as beneficial."], true),
      K("CRS without polyps", `<p>Begin saline lavage one to three times daily followed by an intranasal corticosteroid. Trial this for two to three months and continue as maintenance if effective.</p><p>For refractory symptoms, the deck lists Augmentin or clindamycin for two to four weeks plus a prednisone taper for 10–15 days. Persistent symptoms despite medical therapy may require endoscopic sinus surgery.</p>`,
      ["What is first-line treatment for CRS without nasal polyps?", "Saline lavage followed by an intranasal corticosteroid", ["A biologic agent immediately", "Antifungal monotherapy", "Long-term oxymetazoline"], "Saline and topical steroid form the initial regimen."],
      ["CRS without polyps remains refractory after an adequate topical trial. Which next options are listed?", "Oral antibiotic plus prednisone taper, then surgery if still refractory", ["Stop all treatment", "Aspirin desensitization for everyone", "Only an oral antihistamine"], "The deck escalates medical therapy before surgery."], true),
      K("CRS with polyps", `<p>Without major blockage, use saline one to three times daily plus an intranasal corticosteroid. Significant discomfort, anosmia, or an obstructing polyp calls for a 10–15-day oral prednisone or methylprednisolone taper followed by topical maintenance.</p><p>If topical and oral corticosteroids fail, consider sinus surgery or a biologic such as dupilumab, omalizumab, or mepolizumab. Antibiotics are not recommended unless infection is suspected.</p>`,
      ["How is CRS with nonobstructing polyps treated initially?", "Intranasal saline plus an intranasal corticosteroid", ["Routine antibiotics", "Immediate antifungal therapy", "No therapy"], "Topical saline and steroid are first line."],
      ["An obstructing polyp causes anosmia despite topical therapy. What escalation is listed?", "A short oral corticosteroid taper", ["Long-term topical decongestant", "Routine metronidazole", "Allergy testing alone"], "Obstruction or marked anosmia supports an oral steroid course."], true),
      K("Allergic fungal rhinosinusitis", `<p>Endoscopic sinus surgery removes accumulated mucin and debris, establishes drainage, and obtains samples for definitive diagnosis. Histology evaluates eosinophils and fungal elements and excludes tissue or bone invasion.</p><p>Start oral glucocorticoids immediately after surgery. Antifungal treatment is controversial and generally not recommended. While awaiting definitive surgery, the notes support saline and intranasal steroids as initial treatment.</p>`,
      ["What is the central treatment and diagnostic step for allergic fungal rhinosinusitis?", "Endoscopic sinus surgery", ["Long-term topical decongestant", "Antifungal monotherapy", "Observation only"], "Surgery clears disease and provides diagnostic tissue."],
      ["What medication is started immediately after AFRS surgery?", "An oral glucocorticoid", ["Routine antifungal therapy", "A first-generation antihistamine", "High-dose pseudoephedrine"], "The deck begins systemic steroids after surgery."], true)
    ])
  ];
}());
